import java.util.*;
import java.io.*;

public class CFA {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static final long MOD = 998244353L;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    class Point {
        int x;
        int y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve() throws IOException {
        int n = readInt();
        int m = readInt();
        if (n > m) {
            int tmp = n; n = m; m = tmp;
        }

        if (n == 1) {
            m--;
            int[] left = {0, 0, 0, 2, 4, 6};
            long res = (m / 6) * 6 + left[m % 6];
            printLine(res);
            return;
        } else if (n == 2) {
            if (m < 20) {
                printLine(bruteforce(n, m));
            } else {
                printLine(1L * n * m);
            }
            return;
        } else if (n == 3) {
            if (m < 20) {
                printLine(bruteforce(n, m));
            } else {
                long res = 1L * n * m;
                if (res % 2 != 0) res--;
                printLine(res);
            }
            return;
        }

        long total = 1L * n * m;
        if (total % 2 != 0) total--;
        printLine(total);
    }

    int bruteforce(int n, int m) {
        List<Point> evenPoints = new ArrayList<>();
        List<Point> oddPoints = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) {
                    evenPoints.add(new Point(i, j));
                } else {
                    oddPoints.add(new Point(i, j));
                }
            }
        }

        boolean[][] matchMatrix = new boolean[evenPoints.size()][oddPoints.size()];
        for (int i = 0; i < evenPoints.size(); i++) {
            for (int j = 0; j < oddPoints.size(); j++) {
                int dist = Math.abs(evenPoints.get(i).x - oddPoints.get(j).x) + Math.abs(evenPoints.get(i).y - oddPoints.get(j).y);
                if (dist == 3) {
                    matchMatrix[i][j] = true;
                }
            }
        }
        return 2 * maxMatching(matchMatrix);
    }

    int maxMatching(boolean[][] graph) {
        int n1 = graph.length;
        int n2 = n1 == 0 ? 0 : graph[0].length;
        int[] match = new int[n2];
        Arrays.fill(match, -1);
        int count = 0;
        for (int u = 0; u < n1; u++) {
            boolean[] visited = new boolean[n1];
            if (dfs(u, graph, match, visited))
                count++;
        }
        return count;
    }

    boolean dfs(int u, boolean[][] graph, int[] match, boolean[] visited) {
        visited[u] = true;
        for (int v = 0; v < match.length; v++) {
            if (graph[u][v] && (match[v] == -1 || !visited[match[v]] && dfs(match[v], graph, match, visited))) {
                match[v] = u;
                return true;
            }
        }
        return false;
    }

    int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                eof = true;
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    void printLine(Object o) {
        out.println(o);
    }

    public CFA() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new CFA();
    }
}
